import 'dart:async'; import 'package:flutter/material.dart'; import 'package:flutter_svg/flutter_svg.dart'; import 'package:google_fonts/google_fonts.dart'; import 'package:video_player/video_player.dart'; import 'package:flutter/services.dart';  class OnboardingScreen extends StatefulWidget {   const OnboardingScreen({super.key});    @override   State<OnboardingScreen> createState() => _OnboardingScreenState(); }  class _OnboardingScreenState extends State<OnboardingScreen> {   final PageController _pageController = PageController();   int _currentPage = 0;   Timer? _autoAdvanceTimer;    final List<Color> _bgColors = [     const Color(0xFFEE9B48),     const Color(0xFF550303),     const Color(0xFF151627),     const Color(0xFFFFF8F2),   ];    @override   void initState() {     super.initState();     _startTimer();   }    void _startTimer() {     _autoAdvanceTimer?.cancel();     _autoAdvanceTimer = Timer.periodic(const Duration(seconds: 7), (timer) {       if (_currentPage < 3) {         _pageController.nextPage(           duration: const Duration(milliseconds: 600),           curve: Curves.easeInOut,         );       } else {         _autoAdvanceTimer?.cancel();       }     });   }    void _onPageChanged(int index) {     setState(() {       _currentPage = index;     });     if (index < 3) {       _startTimer();     } else {       _autoAdvanceTimer?.cancel();     }   }    @override   void dispose() {     _pageController.dispose();     _autoAdvanceTimer?.cancel();     super.dispose();   }    void _onNext() {     if (_currentPage < 3) {       _pageController.nextPage(         duration: const Duration(milliseconds: 600),         curve: Curves.easeInOut,       );     } else {       Navigator.pushReplacementNamed(context, '/preferences');     }   }    @override   Widget build(BuildContext context) {     SystemChrome.setSystemUIOverlayStyle(       SystemUiOverlayStyle(         statusBarColor: Colors.transparent,         statusBarIconBrightness: _currentPage == 3 ? Brightness.dark : Brightness.light,       ),     );      return Scaffold(       body: AnimatedContainer(         duration: const Duration(milliseconds: 460),         curve: Curves.easeInOut,         color: _bgColors[_currentPage],         child: Stack(           children: [             PageView(               controller: _pageController,               onPageChanged: _onPageChanged,               physics: const BouncingScrollPhysics(),               children: [                 _buildPage1(),                 _buildPage2(),                 _buildPage3(),                 const LoginScreenView(),               ],             ),             if (_currentPage < 3)               Positioned(                 bottom: 40,                 left: 24,                 right: 24,                 child: _buildBottomControls(),               ),           ],         ),       ),     );   }    Widget _buildPage1() {     return _OnboardingPage(       isActive: _currentPage == 0,       title: 'Epics\nCome\nAlive.',       subtitle: 'Ramayana, Mahabharata and more ΓÇö\ntold through stunning comic stories.',       videoPath: 'assets/videos/onboarding_epics_come_alive.mp4',       videoWidth: 324,       videoHeight: 182,     );   }    Widget _buildPage2() {     return _OnboardingPage(       isActive: _currentPage == 1,       title: 'Ancient\nWisdom,\nDaily.',       subtitle: 'Mantras, Panchang and festival stories ΓÇö\nevery single day.',       videoPath: 'assets/videos/onboarding_ancient_wisdom_daily.mp4',       videoWidth: 232,       videoHeight: 290,     );   }    Widget _buildPage3() {     return _OnboardingPage(       isActive: _currentPage == 2,       title: 'Play.\nLearn.\nGrow.',       subtitle: 'Earn XP, build streaks and climb the\nleagues ΓÇö learning feels like a game.',       videoPath: 'assets/videos/onboarding_play_learn_grow.mp4',       videoWidth: 324,       videoHeight: 240,       showXpBadge: true,     );   }    Widget _buildBottomControls() {     return Row(       mainAxisAlignment: Ma