),       ],     );   } }  class _OnboardingPage extends StatelessWidget {   final bool isActive;   final String title;   final String subtitle;   final String videoPath;   final double videoWidth;   final double videoHeight;   final bool showXpBadge;    const _OnboardingPage({     required this.isActive,     required this.title,     required this.subtitle,     required this.videoPath,     required this.videoWidth,     required this.videoHeight,     this.showXpBadge = false,   });    @override   Widget build(BuildContext context) {     return SafeArea(       child: Padding(         padding: const EdgeInsets.symmetric(horizontal: 24.0),         child: Column(           crossAxisAlignment: CrossAxisAlignment.start,           children: [             const SizedBox(height: 40),             Stack(               clipBehavior: Clip.none,               alignment: Alignment.center,               children: [                 SizedBox(                   width: double.infinity,                   height: 350,                   child: Center(                     child: SizedBox(                       width: videoWidth,                       height: videoHeight,                       child: ClipRRect(                         borderRadius: BorderRadius.circular(16),                         child: VideoPageIllustration(                           videoPath: videoPath,                           isActive: isActive,                         ),                       ),                     ),                   ),                 ),                 if (showXpBadge)                   Positioned(                     top: 40,                     right: 10,                     child: TweenAnimationBuilder<double>(                       duration: const Duration(milliseconds: 600),                       curve: Curves.elasticOut,                       tween: Tween(begin: 0.0, end: isActive ? 1.0 : 0.0),                       builder: (context, value, child) {                         return Transform